DROP TABLE IF EXISTS `invoices_quotation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `invoices_quotation` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `quotation_number` varchar(20) NOT NULL,
  `client_name` varchar(255) NOT NULL,
  `schedule` varchar(255) NOT NULL,
  `training_venue` varchar(50) NOT NULL,
  `discount` decimal(10,2) NOT NULL,
  `consultant_position` varchar(255) NOT NULL,
  `consultant_name` varchar(20) NOT NULL,
  `consultant_number` varchar(20) NOT NULL,
  `consultant_email` varchar(254) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `user_id` int NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `quotation_number` (`quotation_number`),
  KEY `invoices_quotation_user_id_c465ebef_fk_auth_user_id` (`user_id`),
  CONSTRAINT `invoices_quotation_user_id_c465ebef_fk_auth_user_id` FOREIGN KEY (`user_id`) REFERENCES `auth_user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=218 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

